mapper.insert:
INSERT INTO app_character_member (
    character_id, name, tagline, persona, avatar_url, voice_config_json,
    image_reference_url, is_primary, sort_order, enabled
) VALUES (
    #{characterId}, #{name}, #{tagline}, #{persona}, #{avatarUrl}, #{voiceConfigJson},
    #{imageReferenceUrl}, #{primaryMember}, #{sortOrder}, #{enabled}
)

INSERT INTO app_character_opening (
    character_id, title, summary, scenario_override, is_default, sort_order, enabled
) VALUES (
    #{characterId}, #{title}, #{summary}, #{scenarioOverride}, #{defaultOpening}, #{sortOrder}, #{enabled}
)

INSERT INTO app_character_opening_segment (
    opening_id, speaker_member_id, speaker_type, content, sort_order
) VALUES (
    #{openingId}, #{speakerMemberId}, #{speakerType}, #{content}, #{sortOrder}
)

mapper.delete:
DELETE FROM app_character_opening_segment
WHERE opening_id IN (
    SELECT id FROM app_character_opening WHERE character_id = #{characterId}
)

mapper.update:
UPDATE app_character
SET card_type = #{cardType}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{characterId}

UPDATE app_character
SET ensemble_chat_mode = #{ensembleChatMode}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{characterId}
